const nav = document.getElementById('main-nav');
document.addEventListener('mousemove', (e) => {
    if (e.clientY < 100) nav.classList.add('show-labels');
    else nav.classList.remove('show-labels');
});

const splashEl = document.getElementById('splash-text');
let splashIndex = 0;
function rotateSplash() {
    splashEl.innerText = splashes[splashIndex];
    splashIndex = (splashIndex + 1) % splashes.length;
}
setInterval(rotateSplash, 4000);
rotateSplash();

function createShootingStar() {
    const container = document.getElementById('shooting-stars');
    const star = document.createElement('div');
    star.className = 'shooting-star';
    const x = Math.random() * window.innerWidth + 200;
    const y = Math.random() * (window.innerHeight / 2);
    star.style.left = x + 'px';
    star.style.top = y + 'px';
    const duration = 1000 + Math.random() * 2000;
    star.style.animation = `shoot ${duration}ms linear forwards`;
    container.appendChild(star);
    setTimeout(() => { star.remove(); }, duration);
}

function triggerShootingStars() {
    if (Math.random() > 0.7) { createShootingStar(); }
    setTimeout(triggerShootingStars, 2000 + Math.random() * 3000);
}
triggerShootingStars();

const viewer = document.getElementById('app-viewer');
const dashboard = document.getElementById('dashboard-ui');
const loader = document.getElementById('fetch-loader');
let currentAbortController = null;

async function fetchAndRun(url, targetElement) {
    if (currentAbortController) currentAbortController.abort();
    currentAbortController = new AbortController();
    document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
    targetElement.classList.add('active');
    loader.style.display = 'block';
    dashboard.style.opacity = "0.5";
    try {
        const response = await fetch(url, { signal: currentAbortController.signal });
        if (!response.ok) throw new Error();
        const htmlCode = await response.text();
        viewer.src = "about:blank";
        setTimeout(() => {
            viewer.style.display = "block";
            dashboard.style.opacity = "0"; 
            dashboard.style.pointerEvents = "none";
            viewer.srcdoc = htmlCode;
            loader.style.display = 'none';
        }, 50);
    } catch (error) {
        if (error.name === 'AbortError') return;
        viewer.src = url;
        viewer.style.display = "block";
        dashboard.style.opacity = "0";
        loader.style.display = 'none';
    }
}

document.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', (e) => {
        const url = item.getAttribute('data-url');
        if (url) fetchAndRun(url, item);
        else if (item.id === 'btn-home') loadHome();
    });
});

function loadHome() {
    if (currentAbortController) currentAbortController.abort();
    viewer.style.display = "none";
    viewer.src = "about:blank";
    viewer.srcdoc = "";
    dashboard.style.opacity = "1";
    dashboard.style.pointerEvents = "auto";
    document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
    document.getElementById('btn-home').classList.add('active');
}

function updateClock() {
    const now = new Date();
    const clock = document.getElementById('digital-clock');
    if(clock) clock.innerText = now.toLocaleTimeString('en-GB', { hour12: false });
}
setInterval(updateClock, 1000);
updateClock();
